/* Genuine actual-controller/actual32b cast/dawn snapshots; no shadow availability. */
import fs from'node:fs';import{createInstrumentCaster}from'./instrument-cast-native.mjs';import{installInstrumentApp17}from'./instrument-app17-native.mjs';
const cases=[];for(const profileId of ['current-anstruth','legacy-anstruth','current-ollamh','legacy-ollamh']){const current=profileId.startsWith('current-'),client=createInstrumentCaster({profileId,actorRuleset:current?'2014':'2024'}),e=client.engine;installInstrumentApp17(e);client.ready();const p=e.c.S.instrumentSpells.physical[0],grantId=profileId.endsWith('anstruth')?'cure-wounds':'control-weather',otherGrantId='fly',key=p.spells.find(g=>g.grantId===grantId).budgetKey,otherKey=p.spells.find(g=>g.grantId===otherGrantId).budgetKey,snapshot=()=>({build:structuredClone(e.c.B),state:structuredClone(e.c.S.instrumentSpells),used:structuredClone(e.c.S.used),casting:structuredClone(e.C.spellcasting),spell:structuredClone(e.C.spells.find(row=>row.instrumentSpell?.id===p.id&&row.instrumentSpell.grantId===grantId))});const before=snapshot(),cast=client.cast(grantId,'CHA');if(!cast.ok)throw Error(profileId+' actual native cast failed: '+cast.reason);const after=snapshot(),dawn=client.command('dawn',{dawn:{occurrenceId:'fx-next-dawn-1',ordinal:1},facts:{actualDawnOccurred:true,actualCampaignDawnVerified:true,actualDawnOccurredAfterAdmissions:true}});if(!dawn.ok)throw Error(profileId+' actual dawn failed: '+dawn.reason);cases.push({profileId,id:p.id,grantId,otherGrantId,key,otherKey,before,after,dawn:snapshot()});}
fs.writeFileSync(new URL('./instrument-spells-fx.json',import.meta.url),JSON.stringify({cases},null,2)+'\n');console.log('4 actual native Instrument fixedlevel5/8 cast→dawn snapshot pairs generated');
